import{_ as e,c as a,o as i,a4 as t}from"./chunks/framework.CpVK_f0P.js";const b=JSON.parse('{"title":"常用搭配","description":"","frontmatter":{},"headers":[],"relativePath":"expressions/collocations.md","filePath":"expressions/collocations.md"}'),o={name:"expressions/collocations.md"},l=t('<h1 id="常用搭配" tabindex="-1">常用搭配 <a class="header-anchor" href="#常用搭配" aria-label="Permalink to &quot;常用搭配&quot;">​</a></h1><p>这一页收集可以放进句中或句尾的高频语言块，包括动词搭配、短语动词和 时间短语。它们不一定组成完整句子，需要和人物、时间或具体事情组合使用。</p><h2 id="日常生活搭配" tabindex="-1">日常生活搭配 <a class="header-anchor" href="#日常生活搭配" aria-label="Permalink to &quot;日常生活搭配&quot;">​</a></h2><h3 id="_1-make-a-mistake" tabindex="-1">1. <code>make a mistake</code> <a class="header-anchor" href="#_1-make-a-mistake" aria-label="Permalink to &quot;1. `make a mistake`&quot;">​</a></h3><p>表示“犯错误”。根据语境可以使用 <code>make</code>、<code>made</code> 或 <code>makes</code>。</p><ul><li>I made a mistake in the message.</li><li>Don&#39;t worry if you make a mistake.</li><li>We all make mistakes from time to time.</li></ul><h3 id="_2-make-a-decision" tabindex="-1">2. <code>make a decision</code> <a class="header-anchor" href="#_2-make-a-decision" aria-label="Permalink to &quot;2. `make a decision`&quot;">​</a></h3><p>表示“作出决定”。</p><ul><li>I need more time to make a decision.</li><li>Have you made a decision yet?</li><li>We finally made a decision last night.</li></ul><h3 id="_3-make-plans" tabindex="-1">3. <code>make plans</code> <a class="header-anchor" href="#_3-make-plans" aria-label="Permalink to &quot;3. `make plans`&quot;">​</a></h3><p>表示“制订计划、约好活动”。</p><ul><li>We haven&#39;t made any plans for the weekend.</li><li>It&#39;s hard to make plans this far in advance.</li><li>I made plans to have dinner with a friend.</li></ul><h3 id="_4-take-a-break" tabindex="-1">4. <code>take a break</code> <a class="header-anchor" href="#_4-take-a-break" aria-label="Permalink to &quot;4. `take a break`&quot;">​</a></h3><p>表示“休息一下”。</p><ul><li>Let&#39;s take a short break.</li><li>I need to take a break from the screen.</li><li>We took a break after lunch.</li></ul><h3 id="_5-take-your-time" tabindex="-1">5. <code>take your time</code> <a class="header-anchor" href="#_5-take-your-time" aria-label="Permalink to &quot;5. `take your time`&quot;">​</a></h3><p>表示“不用着急、慢慢来”。人称可以根据对象变化。</p><ul><li>Take your time. There&#39;s no rush.</li><li>You can take your time with the form.</li><li>I told her to take her time and think about it.</li></ul><h3 id="_6-get-ready" tabindex="-1">6. <code>get ready</code> <a class="header-anchor" href="#_6-get-ready" aria-label="Permalink to &quot;6. `get ready`&quot;">​</a></h3><p>表示“做好准备”。后接事情时常用 <code>get ready for ...</code> 或 <code>get ready to ...</code>。</p><ul><li>I need a few minutes to get ready.</li><li>We&#39;re getting ready for dinner.</li><li>She got ready to leave the house.</li></ul><h3 id="_7-get-some-rest" tabindex="-1">7. <code>get some rest</code> <a class="header-anchor" href="#_7-get-some-rest" aria-label="Permalink to &quot;7. `get some rest`&quot;">​</a></h3><p>表示“休息一下、好好休息”。</p><ul><li>You should go home and get some rest.</li><li>I went to bed early to get some rest.</li><li>Try to get some rest before the trip.</li></ul><h3 id="_8-have-trouble-ing" tabindex="-1">8. <code>have trouble ...-ing</code> <a class="header-anchor" href="#_8-have-trouble-ing" aria-label="Permalink to &quot;8. `have trouble ...-ing`&quot;">​</a></h3><p>表示“做某事有困难”，动作使用 <code>-ing</code> 形式。</p><ul><li>I have trouble remembering people&#39;s names.</li><li>Are you having trouble opening the file?</li><li>She had trouble falling asleep last night.</li></ul><h3 id="_9-catch-the-bus-train" tabindex="-1">9. <code>catch the bus / train</code> <a class="header-anchor" href="#_9-catch-the-bus-train" aria-label="Permalink to &quot;9. `catch the bus / train`&quot;">​</a></h3><p>表示“赶上并乘坐公交车或火车”。</p><ul><li>I left early to catch the bus.</li><li>Did you catch the last train?</li><li>We managed to catch the train just in time.</li></ul><h3 id="_10-miss-the-bus-train" tabindex="-1">10. <code>miss the bus / train</code> <a class="header-anchor" href="#_10-miss-the-bus-train" aria-label="Permalink to &quot;10. `miss the bus / train`&quot;">​</a></h3><p>表示“没赶上公交车或火车”。</p><ul><li>I missed the bus this morning.</li><li>I don&#39;t want to miss the last train.</li><li>Hurry up, or we&#39;ll miss the train.</li></ul><h3 id="_11-run-out-of" tabindex="-1">11. <code>run out of ...</code> <a class="header-anchor" href="#_11-run-out-of" aria-label="Permalink to &quot;11. `run out of ...`&quot;">​</a></h3><p>表示“把……用完、没有……了”。</p><ul><li>We ran out of milk.</li><li>We&#39;re running out of clean towels.</li><li>We&#39;re running out of time.</li></ul><h3 id="_12-keep-in-touch" tabindex="-1">12. <code>keep in touch</code> <a class="header-anchor" href="#_12-keep-in-touch" aria-label="Permalink to &quot;12. `keep in touch`&quot;">​</a></h3><p>表示“保持联系”。</p><ul><li>Let&#39;s keep in touch.</li><li>We still keep in touch after all these years.</li><li>It&#39;s hard to keep in touch when everyone is busy.</li></ul><h3 id="_13-pick-up" tabindex="-1">13. <code>pick ... up</code> <a class="header-anchor" href="#_13-pick-up" aria-label="Permalink to &quot;13. `pick ... up`&quot;">​</a></h3><p>表示“取东西、接某人”。代词通常放在 <code>pick</code> 和 <code>up</code> 中间。</p><ul><li>I need to pick up some groceries on my way home.</li><li>Can you pick me up at the station?</li><li>She picked it up from the front desk.</li></ul><h3 id="_14-find-out" tabindex="-1">14. <code>find out ...</code> <a class="header-anchor" href="#_14-find-out" aria-label="Permalink to &quot;14. `find out ...`&quot;">​</a></h3><p>表示“查明、得知”。</p><ul><li>I need to find out when the store closes.</li><li>We found out that the restaurant was full.</li><li>Let me find out what happened.</li></ul><h2 id="工作交流搭配" tabindex="-1">工作交流搭配 <a class="header-anchor" href="#工作交流搭配" aria-label="Permalink to &quot;工作交流搭配&quot;">​</a></h2><h3 id="_15-make-progress" tabindex="-1">15. <code>make progress</code> <a class="header-anchor" href="#_15-make-progress" aria-label="Permalink to &quot;15. `make progress`&quot;">​</a></h3><p>表示“取得进展”。</p><ul><li>We&#39;re making good progress on the project.</li><li>I made some progress on the bug yesterday.</li><li>It&#39;s difficult to make progress without the test data.</li></ul><h3 id="_16-meet-a-deadline" tabindex="-1">16. <code>meet a deadline</code> <a class="header-anchor" href="#_16-meet-a-deadline" aria-label="Permalink to &quot;16. `meet a deadline`&quot;">​</a></h3><p>表示“按时完成，在截止日期前完成”。</p><ul><li>We need to meet the deadline.</li><li>I&#39;m confident that we can meet the deadline.</li><li>The extra help allowed us to meet the deadline.</li></ul><h3 id="_17-miss-a-deadline" tabindex="-1">17. <code>miss a deadline</code> <a class="header-anchor" href="#_17-miss-a-deadline" aria-label="Permalink to &quot;17. `miss a deadline`&quot;">​</a></h3><p>表示“错过截止日期、没有按时完成”。</p><ul><li>We may miss the deadline if the issue isn&#39;t fixed today.</li><li>I don&#39;t want to miss another deadline.</li><li>The team missed the deadline by two days.</li></ul><h3 id="_18-solve-a-problem" tabindex="-1">18. <code>solve a problem</code> <a class="header-anchor" href="#_18-solve-a-problem" aria-label="Permalink to &quot;18. `solve a problem`&quot;">​</a></h3><p>表示“解决问题”。</p><ul><li>This change should solve the problem.</li><li>We need more information before we can solve the problem.</li><li>Restarting the service solved the problem temporarily.</li></ul><h3 id="_19-fix-a-bug" tabindex="-1">19. <code>fix a bug</code> <a class="header-anchor" href="#_19-fix-a-bug" aria-label="Permalink to &quot;19. `fix a bug`&quot;">​</a></h3><p>表示“修复 Bug”。</p><ul><li>I&#39;m trying to fix a bug in the login flow.</li><li>We fixed the bug before the release.</li><li>This change fixes a bug that affects mobile users.</li></ul><h3 id="_20-run-tests" tabindex="-1">20. <code>run tests</code> <a class="header-anchor" href="#_20-run-tests" aria-label="Permalink to &quot;20. `run tests`&quot;">​</a></h3><p>表示“运行测试”。</p><ul><li>I need to run the tests again.</li><li>We ran some tests on the new API.</li><li>Please run the tests before you open a pull request.</li></ul><h3 id="_21-review-code" tabindex="-1">21. <code>review code</code> <a class="header-anchor" href="#_21-review-code" aria-label="Permalink to &quot;21. `review code`&quot;">​</a></h3><p>表示“审查代码”。</p><ul><li>I spent the morning reviewing code.</li><li>Could you review my code when you have time?</li><li>We should review the code before merging it.</li></ul><h3 id="_22-make-a-change" tabindex="-1">22. <code>make a change</code> <a class="header-anchor" href="#_22-make-a-change" aria-label="Permalink to &quot;22. `make a change`&quot;">​</a></h3><p>表示“进行修改”。</p><ul><li>I need to make a small change to the configuration.</li><li>We made a few changes after the review.</li><li>Let me know before you make any changes to the API.</li></ul><h3 id="_23-give-feedback" tabindex="-1">23. <code>give feedback</code> <a class="header-anchor" href="#_23-give-feedback" aria-label="Permalink to &quot;23. `give feedback`&quot;">​</a></h3><p>表示“提供反馈、提出意见”。</p><ul><li>Could you give me some feedback on this design?</li><li>The client gave us useful feedback.</li><li>I&#39;ll give you feedback after I test the new version.</li></ul><h3 id="_24-raise-an-issue" tabindex="-1">24. <code>raise an issue</code> <a class="header-anchor" href="#_24-raise-an-issue" aria-label="Permalink to &quot;24. `raise an issue`&quot;">​</a></h3><p>表示“提出一个问题，提醒大家注意”。</p><ul><li>I&#39;d like to raise an issue with the current approach.</li><li>She raised the issue during the meeting.</li><li>No one raised any issues with the proposal.</li></ul><h3 id="_25-take-a-look-at" tabindex="-1">25. <code>take a look at ...</code> <a class="header-anchor" href="#_25-take-a-look-at" aria-label="Permalink to &quot;25. `take a look at ...`&quot;">​</a></h3><p>表示“看一下、检查一下”，比单独使用 <code>check</code> 更口语化。</p><ul><li>Could you take a look at this error?</li><li>I&#39;ll take a look at the logs after lunch.</li><li>We need someone to take a look at the database.</li></ul><h3 id="_26-run-into-a-problem" tabindex="-1">26. <code>run into a problem</code> <a class="header-anchor" href="#_26-run-into-a-problem" aria-label="Permalink to &quot;26. `run into a problem`&quot;">​</a></h3><p>表示“遇到问题”。</p><ul><li>I ran into a problem during the deployment.</li><li>Let me know if you run into any problems.</li><li>We ran into the same problem last week.</li></ul><h3 id="_27-come-up-with-a-solution" tabindex="-1">27. <code>come up with a solution</code> <a class="header-anchor" href="#_27-come-up-with-a-solution" aria-label="Permalink to &quot;27. `come up with a solution`&quot;">​</a></h3><p>表示“想出解决方案”。</p><ul><li>We need to come up with a better solution.</li><li>She came up with a simple solution to the problem.</li><li>Let&#39;s see if we can come up with a solution today.</li></ul><h3 id="_28-reach-an-agreement" tabindex="-1">28. <code>reach an agreement</code> <a class="header-anchor" href="#_28-reach-an-agreement" aria-label="Permalink to &quot;28. `reach an agreement`&quot;">​</a></h3><p>表示“达成一致”。</p><ul><li>We need to reach an agreement before the meeting ends.</li><li>The two teams finally reached an agreement.</li><li>It may take some time to reach an agreement on the details.</li></ul><h3 id="_29-make-sense" tabindex="-1">29. <code>make sense</code> <a class="header-anchor" href="#_29-make-sense" aria-label="Permalink to &quot;29. `make sense`&quot;">​</a></h3><p>表示“合理、说得通、容易理解”。</p><ul><li>That makes sense to me.</li><li>This part of the requirement doesn&#39;t make sense.</li><li>Does it make sense to handle this on the frontend?</li></ul><h2 id="常见句中和句尾短语" tabindex="-1">常见句中和句尾短语 <a class="header-anchor" href="#常见句中和句尾短语" aria-label="Permalink to &quot;常见句中和句尾短语&quot;">​</a></h2><h3 id="_30-at-the-moment" tabindex="-1">30. <code>at the moment</code> <a class="header-anchor" href="#_30-at-the-moment" aria-label="Permalink to &quot;30. `at the moment`&quot;">​</a></h3><p>表示“目前、此刻”。</p><ul><li>I&#39;m busy at the moment.</li><li>At the moment, we don&#39;t have enough information.</li><li>The service isn&#39;t available at the moment.</li></ul><h3 id="_31-for-now" tabindex="-1">31. <code>for now</code> <a class="header-anchor" href="#_31-for-now" aria-label="Permalink to &quot;31. `for now`&quot;">​</a></h3><p>表示“目前暂时这样”，暗示以后可能改变。</p><ul><li>This solution is good enough for now.</li><li>For now, let&#39;s keep the current behavior.</li><li>We don&#39;t need to change anything for now.</li></ul><h3 id="_32-by-the-end-of-the-day" tabindex="-1">32. <code>by the end of the day</code> <a class="header-anchor" href="#_32-by-the-end-of-the-day" aria-label="Permalink to &quot;32. `by the end of the day`&quot;">​</a></h3><p>表示“不晚于今天结束时”。</p><ul><li>I&#39;ll send you an update by the end of the day.</li><li>We need to finish this by the end of the day.</li><li>The new version should be ready by the end of the day.</li></ul><h3 id="_33-as-soon-as-possible" tabindex="-1">33. <code>as soon as possible</code> <a class="header-anchor" href="#_33-as-soon-as-possible" aria-label="Permalink to &quot;33. `as soon as possible`&quot;">​</a></h3><p>表示“尽快”。</p><ul><li>Please reply as soon as possible.</li><li>We need to fix the issue as soon as possible.</li><li>I&#39;ll get back to you as soon as possible.</li></ul><h3 id="_34-from-time-to-time" tabindex="-1">34. <code>from time to time</code> <a class="header-anchor" href="#_34-from-time-to-time" aria-label="Permalink to &quot;34. `from time to time`&quot;">​</a></h3><p>表示“有时、偶尔”。</p><ul><li>I work from home from time to time.</li><li>We still talk from time to time.</li><li>The app may slow down from time to time.</li></ul><h3 id="_35-once-in-a-while" tabindex="-1">35. <code>once in a while</code> <a class="header-anchor" href="#_35-once-in-a-while" aria-label="Permalink to &quot;35. `once in a while`&quot;">​</a></h3><p>表示“偶尔”，比 <code>from time to time</code> 更口语化。</p><ul><li>I eat out once in a while.</li><li>We all need a break once in a while.</li><li>I still watch that show once in a while.</li></ul><h3 id="_36-at-the-same-time" tabindex="-1">36. <code>at the same time</code> <a class="header-anchor" href="#_36-at-the-same-time" aria-label="Permalink to &quot;36. `at the same time`&quot;">​</a></h3><p>表示“同时”，也可以用于补充另一个需要兼顾的观点。</p><ul><li>I can&#39;t listen and write at the same time.</li><li>The change makes the page faster, but at the same time, it adds complexity.</li><li>Both requests arrived at the same time.</li></ul><h3 id="_37-in-that-case" tabindex="-1">37. <code>in that case</code> <a class="header-anchor" href="#_37-in-that-case" aria-label="Permalink to &quot;37. `in that case`&quot;">​</a></h3><p>表示“既然那样、在那种情况下”。</p><ul><li>In that case, let&#39;s wait until tomorrow.</li><li>We don&#39;t have access? In that case, we need to ask the admin.</li><li>In that case, the simpler option would be better.</li></ul><h3 id="_38-in-general" tabindex="-1">38. <code>in general</code> <a class="header-anchor" href="#_38-in-general" aria-label="Permalink to &quot;38. `in general`&quot;">​</a></h3><p>表示“总体来说、一般而言”。</p><ul><li>In general, I prefer working in the morning.</li><li>The new version performs better in general.</li><li>In general, users don&#39;t need to change this setting.</li></ul><h3 id="_39-on-my-own" tabindex="-1">39. <code>on my own</code> <a class="header-anchor" href="#_39-on-my-own" aria-label="Permalink to &quot;39. `on my own`&quot;">​</a></h3><p>表示“独自、靠自己”。人称可以根据主语变化。</p><ul><li>I learned how to do it on my own.</li><li>I don&#39;t think I can finish this on my own.</li><li>She lives on her own.</li></ul><h3 id="_40-on-time" tabindex="-1">40. <code>on time</code> <a class="header-anchor" href="#_40-on-time" aria-label="Permalink to &quot;40. `on time`&quot;">​</a></h3><p>表示“按时”，即在约定或规定的时间到达或完成。</p><ul><li>The train arrived on time.</li><li>I finished the task on time.</li><li>We need to start the meeting on time.</li></ul><h3 id="_41-in-advance" tabindex="-1">41. <code>in advance</code> <a class="header-anchor" href="#_41-in-advance" aria-label="Permalink to &quot;41. `in advance`&quot;">​</a></h3><p>表示“提前、预先”。</p><ul><li>Thanks for letting me know in advance.</li><li>You need to book a table in advance.</li><li>We should prepare the test data in advance.</li></ul><h3 id="_42-in-the-long-run" tabindex="-1">42. <code>in the long run</code> <a class="header-anchor" href="#_42-in-the-long-run" aria-label="Permalink to &quot;42. `in the long run`&quot;">​</a></h3><p>表示“从长远来看”。</p><ul><li>This will save us time in the long run.</li><li>The cheaper option may cost more in the long run.</li><li>It will be easier to maintain in the long run.</li></ul><h3 id="_43-so-far" tabindex="-1">43. <code>so far</code> <a class="header-anchor" href="#_43-so-far" aria-label="Permalink to &quot;43. `so far`&quot;">​</a></h3><p>表示“到目前为止”，常和现在完成时一起使用。</p><ul><li>Everything has gone well so far.</li><li>So far, we haven&#39;t found any major issues.</li><li>I&#39;ve finished three tasks so far.</li></ul><h3 id="_44-in-the-meantime" tabindex="-1">44. <code>in the meantime</code> <a class="header-anchor" href="#_44-in-the-meantime" aria-label="Permalink to &quot;44. `in the meantime`&quot;">​</a></h3><p>表示“在此期间、与此同时”。</p><ul><li>The food will take twenty minutes. In the meantime, let&#39;s get a drink.</li><li>I&#39;m waiting for their reply. In the meantime, I&#39;ll update the tests.</li><li>The fix won&#39;t be ready today, so use the old version in the meantime.</li></ul><h3 id="_45-at-least" tabindex="-1">45. <code>at least</code> <a class="header-anchor" href="#_45-at-least" aria-label="Permalink to &quot;45. `at least`&quot;">​</a></h3><p>表示“至少”，也可以在纠正或补充观点时使用。</p><ul><li>It will take at least two hours.</li><li>At least we know what caused the problem.</li><li>We should test it at least once before the release.</li></ul>',140),n=[l];function r(h,s,d,u,c,m){return i(),a("div",null,n)}const k=e(o,[["render",r]]);export{b as __pageData,k as default};
